/**
 * Assets oficiais dos produtos da Tomati embutidos diretamente no bundle.
 * Garante que as fotos reais carreguem instantaneamente em qualquer ambiente
 * (AI Studio, celulares, Vercel, abas anônimas, redes móveis) sem depender de disco temporário.
 */

export const DEFAULT_LOGO_BASE64 = "data:image/png;base64,";

export const EMBEDDED_PRODUCT_IMAGES: Record<string, string> = {
  heymu: "data:image/webp;base64,",
  naveia: "data:image/webp;base64,",
  tocca: "data:image/webp;base64,",
  yokk: "data:image/webp;base64,",
  fruittitus: "data:image/webp;base64,",
  banner: "data:image/webp;base64,"
};

export function getFallbackProductImage(nome?: string, index?: number): string | null {
  if (!nome && index === undefined) return null;
  const n = (nome || '').toLowerCase();
  if (n.includes('mu') || index === 0) return EMBEDDED_PRODUCT_IMAGES.heymu;
  if (n.includes('naveia') || index === 1) return EMBEDDED_PRODUCT_IMAGES.naveia;
  if (n.includes('tocca') || index === 2) return EMBEDDED_PRODUCT_IMAGES.tocca;
  if (n.includes('yok') || index === 3) return EMBEDDED_PRODUCT_IMAGES.yokk;
  if (n.includes('fruit') || index === 4) return EMBEDDED_PRODUCT_IMAGES.fruittitus;
  if (n.includes('momento') || n.includes('inesquec') || index === 5) return EMBEDDED_PRODUCT_IMAGES.banner;
  return null;
}
